import unittest
from cfg import load_config

class TestLoader(unittest.TestCase):
    def test_override_int(self):
        cfg = load_config({"port": 80, "host": "x"}, {"APP_PORT": "8080"})
        self.assertEqual(cfg["port"], 8080)
        self.assertEqual(cfg["host"], "x")

    def test_override_float(self):
        cfg = load_config({"rate": 1.5}, {"APP_RATE": "2.5"})
        self.assertEqual(cfg["rate"], 2.5)

    def test_override_bool(self):
        cfg = load_config({"debug": False}, {"APP_DEBUG": "true"})
        self.assertEqual(cfg["debug"], True)

    def test_override_str(self):
        cfg = load_config({"name": "foo"}, {"APP_NAME": "bar"})
        self.assertEqual(cfg["name"], "bar")

    def test_no_override_without_prefix(self):
        cfg = load_config({"port": 80}, {"PORT": "8080"})
        self.assertEqual(cfg["port"], 80)

if __name__ == "__main__":
    unittest.main()

